    for r,i in enumerate(seqs[style]):
        v=vol if r%4==0 else (vol-12 if r%2==0 else vol-20)
        put(p,r0+r,ch,ch_[i]+1,inst,vol=max(v,4))

def drums(p,rows,kick=True,snare=True,hat=True,fill=False,half=False):
